SELECT
CURRENT_DATE() AUDIT_DATE,
'AUDIT_BET_ANNUITY_AMT_MULTIYEAR_AMT'AUDIT_NAME,
'MT_RSTD_BKGS_MEASURE' SRC_TABLE_NAME,
'MT_RSTD_BKGS_MSR_ANNUITY' TGT_TABLE_NAME,
'ANNUITY_AMT' AMOUNT_NAME,
ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT  SRC_FISCAL_YEAR_MTH_NUMBER_INT,
ACT.BKGS_MEASURE_TRANS_TYPE_CODE AS SRC_BKGS_MEASURE_TRANS_TYPE_CD,
ACT.BOOKINGS_PROCESS_DATE SRC_BOOKINGS_PROCESS_DATE,
ZEROIFNULL(ACT.MULTIYEAR_AMT) SRC_AMT,
RST.DV_FISCAL_YEAR_MTH_NUMBER_INT TGT_FISCAL_YEAR_MTH_NUMBER_INT,
RST.BKGS_MEASURE_TRANS_TYPE_CODE AS TGT_BKGS_MEASURE_TRANS_TYPE_CD,
RST.BOOKINGS_PROCESS_DATE TGT_BOOKINGS_PROCESS_DATE,
ZEROIFNULL(RST.ANNUITY_AMT) TGT_AMT,
ZEROIFNULL(ACT.MULTIYEAR_AMT)- ZEROIFNULL(RST.ANNUITY_AMT) AUDIT_AMT,
CURRENT_USER AS EDW_CREATE_USER,
CURRENT_USER AS EDW_UPDATE_USER,
CURRENT_TIMESTAMP(0) AS EDW_CREATE_DATETIME,
CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DATETIME
FROM
(
SELECT
RDAYS.FISCAL_YEAR_MONTH_INT DV_FISCAL_YEAR_MTH_NUMBER_INT,
BKGS_MEASURE_TRANS_TYPE_CODE,
BOOKINGS_PROCESS_DATE,
SUM(ZEROIFNULL(DV_MULTIYEAR_US_NET_AMT  ))  MULTIYEAR_AMT
FROM
{{ source('raw', 'MT_RSTD_BKGS_MEASURE') }} NBM
INNER JOIN
{{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} RDAYS
ON NBM.BOOKINGS_PROCESS_DATE = RDAYS.CALENDAR_DATE
INNER JOIN
{{ source('raw', 'R_FISCAL_MONTH_TO_YEAR') }} RFM
ON RFM.FISCAL_YEAR_AGE     IN (1,0)
/*ON (
( RFM.PREVIOUS_FSCL_MONTH_FLAG      = 'Y' 
AND CURRENT_DATE BETWEEN RFM.FISCAL_MONTH_END_DATE + 1 AND  RFM.FISCAL_MONTH_END_DATE + 6) 
OR  RFM.CURRENT_FISCAL_MONTH_FLAG    = 'Y'   
)*/
WHERE RFM.FISCAL_YEAR_MONTH_INT = DV_FISCAL_YEAR_MTH_NUMBER_INT
AND COLLATE( SERVICE_FLG, 'en-ci-rtrim') = 'Y'
AND COLLATE( DV_ANNUALIZED_FLG, 'en-ci-rtrim') = 'N'
GROUP BY 1,2,3
) ACT
FULL OUTER JOIN
(
SELECT
RDAYS.FISCAL_YEAR_MONTH_INT DV_FISCAL_YEAR_MTH_NUMBER_INT,
BKGS_MEASURE_TRANS_TYPE_CODE,
BOOKINGS_PROCESS_DATE,
SUM(ZEROIFNULL(DV_ANNUITY_AMT))  ANNUITY_AMT
FROM
{{ source('raw', 'MT_RSTD_BKGS_MSR_ANNUITY') }} NBM
INNER JOIN
{{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} RDAYS
ON NBM.BOOKINGS_PROCESS_DATE = RDAYS.CALENDAR_DATE
INNER JOIN
{{ source('raw', 'R_FISCAL_MONTH_TO_YEAR') }} RFM
ON RFM.FISCAL_YEAR_AGE     IN (1,0)
/*ON (
( RFM.PREVIOUS_FSCL_MONTH_FLAG      = 'Y' 
AND CURRENT_DATE BETWEEN RFM.FISCAL_MONTH_END_DATE + 1 AND  RFM.FISCAL_MONTH_END_DATE + 6) 
OR RFM.CURRENT_FISCAL_MONTH_FLAG    = 'Y'   
)*/
WHERE RFM.FISCAL_YEAR_MONTH_INT = DV_FISCAL_YEAR_MTH_NUMBER_INT
AND COLLATE( DV_SRVC_BOOKINGS_TYPE, 'en-ci-rtrim') = 'ANNUITY'
GROUP BY 1,2,3
) RST
ON
ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT = RST.DV_FISCAL_YEAR_MTH_NUMBER_INT
AND ACT.BKGS_MEASURE_TRANS_TYPE_CODE = RST.BKGS_MEASURE_TRANS_TYPE_CODE
AND ACT.BOOKINGS_PROCESS_DATE = RST.BOOKINGS_PROCESS_DATE

WHERE  AUDIT_AMT  NOT BETWEEN  -1 AND 1